args.sql:
ALTER TABLE transactions
ADD COLUMN adjusted_escrow_rate NUMERIC;

UPDATE transactions
SET adjusted_escrow_rate = m.esccomprate
FROM markets m
WHERE transactions.mktref = m.mktregistry;

CREATE INDEX idx_anomaly_detection
ON transactions (adjusted_escrow_rate);

